bool tail_less(const CatalogueBall& a, const CatalogueBall& b) noexcept {
  for (u32 k = 1; k < 4; ++k)
    if (a.support[k] != b.support[k]) return idx(a.support[k]) < idx(b.support[k]);
  return false;
}

